components.css:
.preview {
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  color: #b8e5e8;
  padding: 0 8px;
}
.preview[data-mode='party'] {
  color: #ffb389;
}
.preview[data-mode='practice'] {
  color: #b4d9b5;
}
.routeArt {
  display: block;
  width: 100%;
  height: 138px;
  margin-top: -8px;
}
.previewCopy h3 {
  margin: 10px 0 8px;
  font:
    italic 800 34px/1.1 'Frostbound Display',
    sans-serif;
  letter-spacing: -0.015em;
  text-transform: uppercase;
}
.previewCopy p {
  margin: 0;
  max-width: 32ch;
  font-size: 13px;
  line-height: 1.6;
  color: var(--menu-muted);
}
.previewCopy ul {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 16px 0 0;
  padding: 0;
  list-style: none;
  font-size: 11px;
  color: #d4e5e6;
}
.previewCopy li {
  display: flex;
  align-items: center;
  gap: 6px;
}
.previewCopy li::before {
  content: '';
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
}
@media (max-width: 600px) {
.preview {
    padding: 0;
  }
.routeArt {
    display: none;
  }
.previewCopy h3 {
    font-size: 28px;
    margin-top: 0;
  }
.previewCopy p {
    max-width: none;
  }
.previewCopy ul {
    margin-top: 10px;
  }
}

.picker {
  min-width: 0;
  border: 0;
  padding: 0;
  margin: 0 0 22px;
  text-align: left;
}
.picker legend {
  padding: 0 0 10px;
  color: #eef8f3;
  font-size: 13px;
  font-weight: 600;
}
.picker > div {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.picker label {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 14px 12px;
  border: 1px solid #b4c9ce29;
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
}
.picker label:has(input:checked) {
  background: #d8f2f0;
  border-color: #d8f2f0;
}
.picker label:has(input:focus-visible) {
  outline: 2px solid #ffb389;
  outline-offset: 3px;
}
.picker input {
  flex-shrink: 0;
  margin: 3px 0 0;
  accent-color: #285965;
}
.picker strong {
  display: block;
  color: #eef8f3;
  font-size: 14px;
  font-weight: 650;
}
.picker small {
  display: block;
  margin-top: 5px;
  color: #b4c9ce;
  font-size: 12px;
  line-height: 1.5;
}
.picker label:has(input:checked) strong {
  color: #123c48;
}
.picker label:has(input:checked) small {
  color: #365966;
}
.picker:disabled {
  opacity: 0.6;
}
.picker:disabled label {
  cursor: default;
}
@media (max-width: 360px) {
  .picker > div {
    grid-template-columns: 1fr;
  }
}
